    deep: { rx: 40, ry: 18, y: 42, leftRotation: 0, rightRotation: 0, lid: 0.72 },
    narrow: { rx: 44, ry: 13, y: 40, leftRotation: 0, rightRotation: 0, lid: 0.82 },
    upturned: { rx: 41, ry: 20, y: 40, leftRotation: -5, rightRotation: 5, lid: 0.46 },
